import json, re
from pathlib import Path

issue = Path('/app/inputs/issue.md').read_text()
notes = Path('/app/inputs/release-notes.md').read_text()
approvals = json.loads(Path('/app/records/approvals.json').read_text())

version_match = re.search(r'(?im)^\s*(?:version|release)\s*:\s*([^\n]+)', issue)
component_match = re.search(r'(?im)^\s*component\s*:\s*([^\n]+)', issue)
if not version_match or not component_match:
    raise SystemExit('Could not extract version/component from issue.md')
version = version_match.group(1).strip().strip('`*_')
component = component_match.group(1).strip().strip('`*_')

bugfix_match = re.search(r'(?i)(\d+)\s+bug\s*fix(?:es)?', notes)
if not bugfix_match:
    raise SystemExit('Could not extract bug-fix count from release-notes.md')
bugfixes = int(bugfix_match.group(1))

# Support the common approvals record shapes while requiring an exact version match.
approved = None
if isinstance(approvals, dict):
    if isinstance(approvals.get('approvals'), list):
        records = approvals['approvals']
    elif version in approvals:
        approved = approvals[version]
        records = []
    else:
        records = [approvals]
else:
    records = approvals
if approved is None:
    for record in records:
        if isinstance(record, dict) and str(record.get('version')) == version:
            approved = record.get('approved')
            break
if approved is None or not isinstance(approved, bool):
    raise SystemExit(f'No authoritative boolean approval found for version {version!r}')

digest = {'version': version, 'component': component, 'bugfixes': bugfixes, 'approved': approved}
Path('/app/digest.json').write_text(json.dumps(digest, indent=2) + '\n')
print(json.dumps(digest, indent=2))
